 // Explicit service intervals and workshop deadlines; estimates never enter the ledger.
 const maintenanceApi=globalThis.RodavoltMaintenance;
 function maintenancePlanForm(id=null,vehicleId='RV-001'){const p=id?maintenanceApi.lookup(ops,id):null,v=M.vehicles(ops).find(v=>v.id===(p?.vehicleId||vehicleId))||M.vehicles(ops)[0];return `<form id="maintenance-plan-form">${p?`<input type="hidden" name="planId" value="${p.id}">`:''}<div class="notice">Escolha os intervalos conforme manual e orientação da oficina. Vence pelo km ou pela data que chegar primeiro. Valores aqui são estimativas; não geram despesa.</div><div class="fields gap">${p?`<input type="hidden" name="vehicleId" value="${p.vehicleId}">${input('vehicleLabel','Carro',p.vehicleId,'disabled')}`:select('vehicleId','Carro',v.id,M.vehicles(ops).map(v=>[v.id,v.id+' · '+v.model]))}${input('title','Cuidado / serviço',p?.title||'','required maxlength="150" placeholder="Ex.: troca de óleo e filtro"')}${input('intervalKm','A cada quantos km? (opcional)',p?.intervalKm??'','type="number" min="1" step="1" placeholder="Preencha km, dias ou os dois"')}${input('intervalDays','A cada quantos dias? (opcional)',p?.intervalDays??'','type="number" min="1" step="1"')}${input('lastKm','Km do último cuidado',p?.lastKm??v.km,'type="number" min="0" step="1" required')}${input('lastDate','Data do último cuidado',p?.lastDate||K.operatingDate,'type="date" required')}${input('warningKm','Avisar quando faltar · km',p?.warningKm??0,'type="number" min="0" step="1" required')}${input('estimatedCost','Custo estimado · R$ (opcional)',p?.estimatedCost??'','type="number" min="0" step="0.01"')}</div><label class="field gap">Origem das condições e observação<textarea name="note" rows="2" maxlength="1000" required placeholder="Manual, orientação da oficina ou condição conferida pela gestão.">${esc(p?.note||'')}</textarea></label><div class="form-actions"><button type="submit" class="btn primary">Salvar plano de cuidados</button></div><p class="caption">Nenhuma periodicidade é aplicada sem sua confirmação. O hodômetro atual precisa estar atualizado na frota/vistoria.</p></form>`;}
 function maintenancePanel(){const plans=maintenanceApi.summary(ops),open=ops.service.filter(s=>s.status==='open');return panel('Cuidados programados',`<p class="caption">Intervalos escolhidos por você, com prazo da oficina e histórico. O custo estimado serve para preparar o caixa; somente a conclusão da ordem registra o custo efetivo.</p><div class="actions">${btn('Novo plano de cuidados','maintenance-configure','primary')}${btn('Abrir ordem com prazo','maintenance-open')}</div>${plans.length?table(['Carro / cuidado','Próximo km / data','Situação','Ações'],plans.map(p=>`<tr><td><strong>${esc(p.vehicleId)} · ${esc(p.title)}</strong><small>${p.estimatedCost===null?'Sem estimativa de custo':'Estimativa '+cash(p.estimatedCost)}</small></td><td>${p.nextKm===null?'Sem intervalo em km':num(p.nextKm)+' km'}<small>${p.nextDate?date(p.nextDate):'Sem intervalo em dias'}</small></td><td>${tag(!p.active?'Pausado':p.openOrderId?'Ordem aberta':p.due?'Prazo / km atingido':p.nearKm?'Km próximo':'Programado',!p.active?'':p.due||p.nearKm?'amber':'green')}<small>${p.remainingKm===null?'':Math.max(0,p.remainingKm)+' km até o cuidado'}</small></td><td>${btn('Editar','maintenance-configure','',`data-id="${p.id}"`)}${p.active&&!p.openOrderId?btn('Abrir ordem','maintenance-open','',`data-plan-id="${p.id}"`):''}${btn(p.active?'Pausar':'Retomar','maintenance-toggle','',`data-id="${p.id}"`)}</td></tr>`).join('')):'<p class="caption gap">Ainda não há plano recorrente. Cadastre os intervalos definidos para o carro efetivo.</p>'}${open.length?`<div class="gap"><h3>Oficina: ordens em andamento</h3>${open.map(s=>row(esc(s.id)+' · '+esc(s.title),s.due?date(s.due):'Prazo pendente',esc(s.vehicleId||'RV-001')+(s.note?' · '+esc(s.note):''))+btn('Concluir com data e km','maintenance-close','',`data-id="${s.id}"`)).join('')}</div>`:''}<details class="gap"><summary>Ver histórico de cuidados concluídos</summary>${table(['Ordem / carro','Data / km','Custo efetivo'],maintenanceApi.ensure(ops).completions.slice().reverse().map(c=>`<tr><td>${esc(c.serviceId)} · ${esc(c.vehicleId)}</td><td>${date(c.date)}<small>${num(c.km)} km</small></td><td>${cash(c.cost)}</td></tr>`).join(''))}</details>`);}
 function driverMaintenanceView(driverId){const plans=maintenanceApi.driverView(ops,driverId);if(!plans.length)return '';return `<section class="driver-paper gap"><h2>Próximos cuidados do carro</h2>${plans.map(p=>`<div class="row"><div>${esc(p.title)}<small>${p.nextDate?'Até '+date(p.nextDate):''}${p.nextDate&&p.nextKm!==null?' ou ':''}${p.nextKm===null?'':num(p.nextKm)+' km'}</small></div><strong>${p.openOrderId?'Oficina agendada':p.overdueKm||p.overdueDate?'Fale com a RODAVOLT':p.nearKm?'Está chegando':'Programado'}</strong></div>`).join('')}<p>Avise se perceber algum problema. Pare em local seguro antes de falar pelo aplicativo.</p></section>`;}
 function maintenanceAction(action,e){if(!action.startsWith('maintenance-'))return false;if(mode!=='admin')throw new RangeError('A gestão organiza os planos e as ordens de manutenção.');if(action==='maintenance-configure'){open(e.dataset.id?'Editar plano de cuidados':'Configurar cuidado recorrente',maintenancePlanForm(e.dataset.id||null,e.dataset.vehicleId));return true;}if(action==='maintenance-panel'){open('Cuidados e oficina',maintenancePanel());return true;}if(action==='maintenance-toggle'){const p=maintenanceApi.lookup(ops,e.dataset.id);open(p.active?'Pausar plano':'Retomar plano',`<form id="maintenance-toggle-form"><input type="hidden" name="entityId" value="${p.id}"><input type="hidden" name="active" value="${p.active?'no':'yes'}"><label class="field">Motivo da alteração<textarea name="note" rows="2" required maxlength="1000"></textarea></label><div class="form-actions"><button class="btn primary" type="submit">Confirmar ${p.active?'pausa':'retomada'}</button></div></form>`);return true;}if(action==='maintenance-open'){const p=e.dataset.planId?maintenanceApi.lookup(ops,e.dataset.planId):null;open('Abrir manutenção com prazo',`<form id="maintenance-open-form">${p?`<input type="hidden" name="planId" value="${p.id}"><input type="hidden" name="vehicleId" value="${p.vehicleId}">${row('Plano / carro',esc(p.title)+' · '+p.vehicleId)}`:select('vehicleId','Carro','RV-001',M.vehicles(ops).map(v=>[v.id,v.id+' · '+v.model]))}<div class="fields gap">${input('title','Serviço necessário',p?.title||'','required maxlength="150"')}${input('due','Prazo combinado com a oficina',K.operatingDate,'type="date" required')}</div><label class="field gap">Combinado e orientação<textarea name="note" required rows="2" maxlength="1000"></textarea></label><div class="form-actions"><button class="btn primary" type="submit">Abrir ordem e registrar prazo</button></div><p class="caption">O carro fica indisponível. O custo efetivo será registrado quando o serviço for concluído.</p></form>`);return true;}if(action==='maintenance-close'){const s=ops.service.find(s=>s.id===e.dataset.id);if(!s)throw new RangeError('Ordem não encontrada.');const v=M.vehicles(ops).find(v=>v.id===(s.vehicleId||'RV-001'));open('Concluir manutenção e próximo cuidado',`<form id="maintenance-close-form"><input type="hidden" name="entityId" value="${s.id}">${row('Ordem / carro',esc(s.id)+' · '+esc(s.title),esc(v.id))}<div class="fields gap">${input('date','Data efetiva da conclusão',K.operatingDate,'type="date" required')}${input('km','Hodômetro na conclusão',v.km,'type="number" min="0" step="1" required')}${input('cost','Custo efetivo · R$',s.cost||0,'type="number" min="0" step="0.01" required')}</div><label class="check gap"><input type="checkbox" name="confirm" required>Conferi o custo, a data, os km e a liberação da oficina.</label><div class="form-actions"><button class="btn primary" type="submit">Concluir e lançar custo uma vez</button></div><p class="caption">Somente o plano vinculado à ordem terá os intervalos reiniciados. Outros cuidados permanecem pendentes.</p></form>`);return true;}return false;}
 function maintenanceSubmit(form,f){if(!form.id.startsWith('maintenance-'))return false;if(mode!=='admin')throw new RangeError('A gestão organiza os cuidados do carro.');let message='Plano de cuidados atualizado.';if(form.id==='maintenance-plan-form'){maintenanceApi.configure(ops,{planId:String(f.get('planId')||'')||undefined,vehicleId:String(f.get('vehicleId')),title:String(f.get('title')),intervalKm:f.get('intervalKm'),intervalDays:f.get('intervalDays'),lastKm:Number(f.get('lastKm')),lastDate:String(f.get('lastDate')),warningKm:Number(f.get('warningKm')),estimatedCost:f.get('estimatedCost'),note:String(f.get('note'))});}else if(form.id==='maintenance-toggle-form'){maintenanceApi.setActive(ops,String(f.get('entityId')),f.get('active')==='yes',String(f.get('note')));}else if(form.id==='maintenance-open-form'){maintenanceApi.openOrder(ops,{planId:String(f.get('planId')||'')||undefined,vehicleId:String(f.get('vehicleId')),title:String(f.get('title')),due:String(f.get('due')),note:String(f.get('note'))});message='Ordem aberta com prazo; custo ainda não lançado.';}else if(form.id==='maintenance-close-form'){if(!f.has('confirm'))throw new RangeError('Confirme as informações da conclusão.');const id=String(f.get('entityId')),data={date:String(f.get('date')),km:Number(f.get('km'))};maintenanceApi.validateCompletion(ops,id,data);M.closeService(ops,id,Number(f.get('cost')),data);revision=null;message='Cuidado concluído, custo lançado uma vez e próximos intervalos atualizados.';}else return false;close();render();persist();open('Cuidados e oficina',maintenancePanel());toast(message);return true;}
